pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testRegression_property() public {
        vm.roll(1);
        address alice = address(0x123);
        vm.deal(alice, 10 ether);
        vm.prank(alice);
        (bool success, ) = address(c).call{value: 10 ether}("");
        require(success, "fallback call failed");
        assertTrue(address(c).balance == 10 ether, "Bug: balance was transferred when it should not have been");
    }
}
